<script setup>
import {ref,watch} from 'vue';
import {liveNumericValue,formatNumericValue,resolveNumericCommit,syncNumericDraft} from '../numeric-input.js';
const props=defineProps({modelValue:[String,Number,Boolean],label:String,type:{default:'number'},min:Number,max:Number,step:{default:1},unit:String,options:Array});const emit=defineEmits(['update:modelValue','commit']);function change(e){let value=props.type==='toggle'?e.target.checked:props.type==='number'||props.type==='range'?Number(e.target.value):e.target.value;if(typeof value==='number'){if(!Number.isFinite(value))return;if(props.min!==undefined)value=Math.max(props.min,value);if(props.max!==undefined)value=Math.min(props.max,value);}emit('update:modelValue',value);}
const numberDraft=ref(formatNumericValue(props.modelValue));let numberEditing=false,numberDirty=false;
watch(()=>props.modelValue,value=>{numberDraft.value=syncNumericDraft(numberDraft.value,value,numberEditing);});
function startNumber(e){if(props.type!=='number')return;numberEditing=true;numberDirty=false;numberDraft.value=e.target.value;}
function inputNumber(e){numberDraft.value=e.target.value;numberDirty=true;const value=liveNumericValue(numberDraft.value,props);if(value!==null)emit('update:modelValue',value);}
function commitNumber(){const value=resolveNumericCommit(numberDraft.value,props.modelValue,props);numberDraft.value=formatNumericValue(value);numberDirty=false;if(value!==props.modelValue)emit('update:modelValue',value);emit('commit');}
function finishNumber(){if(props.type!=='number')return;if(numberDirty)commitNumber();numberEditing=false;}
</script>
<template><label class="aw-control" :class="['control-'+type]"><span>{{label}}</span><template v-if="type==='toggle'"><input type="checkbox" :checked="modelValue" :aria-label="label" @change="change($event);emit('commit')"/><i></i></template><select v-else-if="type==='select'" :value="modelValue" :aria-label="label" @change="change($event);emit('commit')"><option v-for="o in options" :key="o.id??o" :value="o.id??o">{{o.name??o}}</option></select><div v-else-if="type==='range'" class="aw-range-control"><input type="range" :value="modelValue" :min="min" :max="max" :step="step" :aria-label="label" @input="change" @change="emit('commit')"/><span>{{Number(modelValue).toFixed(step<1?step<.1?2:1:0)}}{{unit}}</span></div><div v-else-if="type==='color'" class="aw-color-control"><input type="color" :value="modelValue" :aria-label="label" @input="change" @change="emit('commit')"/><input :value="modelValue" :aria-label="label+' HEX'" maxlength="7" @change="/^#[0-9a-f]{6}$/i.test($event.target.value)?(emit('update:modelValue',$event.target.value),emit('commit')):($event.target.value=modelValue)"/></div><div v-else class="aw-input-unit"><input :type="type" :value="type==='number'?numberDraft:modelValue" :min="min" :max="max" :step="step" :aria-label="label" @focus="startNumber" @input="type==='number'?inputNumber($event):change($event)" @change="type==='number'?commitNumber():emit('commit')" @blur="finishNumber"/><small v-if="unit">{{unit}}</small></div></label></template>
